class Solution
{
    int n;
    vector<int> differences;
    string target;
    int length(int mask)
    {
        int result = 0, skipped = 0;
        for (int i = 0; i < n; ++i)
        {
            if (mask & (1 << i))
            {
                if (skipped) ++result;
                skipped = 0;
                ++result;
            } else
            {
                ++skipped;
            }
        }
        if (skipped) ++result;
        return result;
    }
    string encode(int mask)
    {
        string result;
        int skipped = 0;
        for (int i = 0; i < n; ++i)
        {
            if (mask & (1 << i))
            {
                if (skipped) result += to_string(skipped);
                skipped = 0;
                result += target[i];
            } else
            {
                ++skipped;
            }
        }
        if (skipped) result += to_string(skipped);
        return result;
    }
public:
    string minAbbreviation(string target, vector<string>& dictionary)
    {
        this->target = target;
        n = target.size();
        differences.clear();
        for (const string& word : dictionary) {
            if ((int)word.size() != n) continue;
            int diff = 0;
            for (int i = 0; i < n; ++i)
            {
                if (word[i] != target[i]) diff |= 1 << i;
            }
            differences.push_back(diff);
        }
        if (differences.empty()) return to_string(n);
        int bestMask = (1 << n) - 1, bestLength = INT_MAX;
        for (int mask = 0; mask < (1 << n); ++mask)
        {
            int len = length(mask);
            if (len >= bestLength) continue;
            bool unique = true;
            for (int diff : differences) {
                if ((mask & diff) == 0)
                {
                    unique = false;
                    break;
                }
            }
            if (unique)
            {
                bestLength = len;
                bestMask = mask;
            }
        }
        return encode(bestMask);
    }
};
